const plane = new THREE.Plane();
plane.setFromNormalAndCoplanarPoint(
camera.up,
camera.position
);
const raycaster = new THREE.Raycaster();
raycaster.setFromCamera(mouse, camera);
const intersect = raycaster.ray.intersectPlane(plane);
if (intersect) {
draggedSphere.position.copy(intersect);
}
});
window.addEventListener('mouseup', () => {
isDragging = false;
if (draggedSphere) {
draggedSphere.material.color.setHSL(
(noise.simplex2(draggedSphere.position.x, draggedSphere.position.y) + 1) / 2,
0.7 + noise.simplex2(draggedSphere.position.z, draggedSphere.position.x) * 0.3,
0.5 + noise.simplex2(draggedSphere.position.y, draggedSphere.position.z) * 0.5
);
draggedSphere = null;
}
});
